/**
 * Locally bundled fallback artwork.
 *
 * Original abstract vector posters generated by this project (no third-party
 * rights involved, so they are safe to ship and safe to show). They are used
 * in two situations only:
 *   • an <img> fails to load, so a card never renders as a broken tile;
 *   • the Openverse API is unreachable, so the feed is never blank.
 * They are abstract by construction, which also means they can never contain
 * explicit or horror imagery.
 */

interface ArtworkSpec {
  id: string;
  title: string;
  background: string;
  shapes: string;
  width: number;
  height: number;
}

