const cache = new Map<string, string>();

function encode(svg: string): string {
  return `data:image/svg+xml;utf8,${encodeURIComponent(svg)}`;
}

/** Data URI for one piece of bundled artwork. */
export function artworkDataUri(index: number): string {
  const spec = SPECS[((index % SPECS.length) + SPECS.length) % SPECS.length];
  const hit = cache.get(spec.id);
  if (hit) return hit;
  const svg =
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${spec.width} ${spec.height}" width="${spec.width}" height="${spec.height}">` +
    `<rect width="${spec.width}" height="${spec.height}" fill="${spec.background}"/>${spec.shapes}</svg>`;
  const uri = encode(svg);
  cache.set(spec.id, uri);
  return uri;
}

/**
 * Bundled artwork as pins, used when the API cannot be reached. Ratio variety
 * mirrors the reference (0.47–0.83) so the masonry stays staggered.
 */
export function fallbackPins(count = SPECS.length): Pin[] {
  return SPECS.slice(0, Math.max(1, Math.min(count, SPECS.length))).map((spec, index) => ({
    id: spec.id,
    title: spec.title,
    imageUrl: artworkDataUri(index),
    originalUrl: artworkDataUri(index),
    width: spec.width,
    height: spec.height,
    creator: 'Pinspire (bundled artwork)',
    license: 'cc0',
    licenseVersion: '1.0',
    licenseUrl: 'https://creativecommons.org/publicdomain/zero/1.0/',
    attribution:
      `“${spec.title}” is original vector artwork bundled with this project and released under CC0 1.0.`,
    local: true,
    badge: index === 5 ? '3/9' : index === 14 ? '2/6' : undefined,
  }));
}

/** Neutral placeholder shown when a single image URL turns out to be broken. */
export function brokenImageReplacement(index: number): string {
  return artworkDataUri(index);
}
